/**
 * @file task_ble.h
 * @brief BLE task — advertises as "WatchWise" and sends SpO2 and step-count
 *        notifications to a connected BLE central (phone).
 *
 * Uses the WICED BT stack (wiced_bt_* API) via the btstack-integration
 * middleware. The GATT database is generated by BT Configurator.
 *
 * GATT Services (defined in BT Configurator):
 *   WatchWise Custom Health Service (128-bit UUID):
 *     - SpO2  characteristic: read + notify, 1 byte (%)
 *     - Steps characteristic: read + notify, 4 bytes LE uint32
 *
 * Testing: nRF Connect → scan "WatchWise" → Connect → enable notifications
 * on SpO2 and StepCount in the WatchWise Custom Service.
 */
#ifndef TASK_BLE_H
#define TASK_BLE_H

#include "FreeRTOS_Api.h"
#include <stdbool.h>
#include <stdint.h>

/** True while a BLE central is connected. Safe to read from any task. */
extern volatile bool ble_connected;

/**
 * @brief Create the BLE task. Call once from system_control_initialize()
 *        before vTaskStartScheduler(). Stack init happens asynchronously
 *        inside the task after the scheduler starts.
 */
void ble_task_initialize(void);

/** FreeRTOS task function — do not call directly. */
void task_ble(void *pvParameters);

#endif /* TASK_BLE_H */
